import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
// Font Loader Hook
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// Schema Definition


export type AwarenessStagesProps = Record<string, any>;

// SVG Components
const MarkerArrow: React.FC<{ color: string; progress: number }> = ({ color, progress }) => {
  // Simple hand-drawn chevron style
  const pathLength = 100; // estimated
  const strokeDashoffset = interpolate(progress, [0, 1], [pathLength, 0]);
  
  return (
    <svg width="100%" height="100%" viewBox="0 0 100 100" style={{ overflow: "visible" }}>
      <path
        d="M 20 10 L 60 50 L 20 90"
        stroke={color}
        strokeWidth="12"
        fill="none"
        strokeLinecap="round"
        strokeLinejoin="round"
        style={{
          strokeDasharray: pathLength,
          strokeDashoffset,
          filter: "drop-shadow(2px 2px 0px rgba(0,0,0,0.1))"
        }}
      />
      {/* Second stroke for marker effect */}
      <path
        d="M 25 15 L 65 50 L 25 85"
        stroke={color}
        strokeWidth="4"
        fill="none"
        strokeLinecap="round"
        strokeLinejoin="round"
        opacity={0.5}
        style={{
          strokeDasharray: pathLength,
          strokeDashoffset,
        }}
      />
    </svg>
  );
};

const RoughBox: React.FC<{
  width: number;
  height: number;
  color: string;
  className?: string;
  style?: React.CSSProperties;
  children?: React.ReactNode;
}> = ({ width, height, color, style, children }) => {
  // Create a clip path that looks slightly jagged/hand-drawn
  const clipPath = `polygon(
    2% 0%, 
    98% 1%, 
    100% 98%, 
    1% 100%
  )`;
  
  return (
    <div
      style={{
        width,
        height,
        backgroundColor: color,
        clipPath,
        position: 'relative',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        boxShadow: '4px 4px 0px rgba(0,0,0,0.1)',
        ...style,
      }}
    >
      {children}
    </div>
  );
};

const StageColumn: React.FC<{
  index: number;
  title: string;
  description: string;
  headerColor: string;
  bodyColor: string;
  textColor: string;
  delay: number;
  frame: number;
  fps: number;
  width: number;
  headerHeight: number;
  bodyHeight: number;
  headerFontSize: number;
  bodyFontSize: number;
}> = ({ 
  index, title, description, headerColor, bodyColor, textColor, delay, frame, fps, width, 
  headerHeight, bodyHeight, headerFontSize, bodyFontSize 
}) => {
  
  const progress = spring({
    frame: frame - delay,
    fps,
    config: { damping: 15, stiffness: 80 }
  });

  const opacity = interpolate(progress, [0, 1], [0, 1]);
  const translateY = interpolate(progress, [0, 1], [50, 0]);
  const rotate = interpolate(progress, [0, 1], [-5, 0]); // Slight tilt in

  // Slight random rotation for "hand-drawn" feel per card
  const staticRotation = (index % 2 === 0 ? 1 : -1) * 0.5;

  return (
    <div
      style={{
        width,
        display: 'flex',
        flexDirection: 'column',
        opacity,
        transform: `translateY(${translateY}px) rotate(${rotate + staticRotation}deg)`,
      }}
    >
      {/* Header */}
      <RoughBox
        width={width}
        height={headerHeight}
        color={headerColor}
        style={{ marginBottom: -5, zIndex: 2, padding: '5%' }} // Overlap slightly
      >
        <h2
          style={{
            color: 'white',
            fontFamily: '"Permanent Marker", cursive',
            fontSize: `${headerFontSize}px`,
            textAlign: 'center',
            margin: 0,
            lineHeight: 1.1,
            wordWrap: 'break-word',
            width: '100%'
          }}
        >
          {title}
        </h2>
      </RoughBox>

      {/* Body */}
      <RoughBox
        width={width}
        height={bodyHeight}
        color={bodyColor}
        style={{ 
            alignItems: 'flex-start', 
            padding: '10% 8%',
            zIndex: 1 
        }}
      >
        <p
          style={{
            color: textColor,
            fontFamily: '"Kalam", cursive',
            fontSize: `${bodyFontSize}px`,
            textAlign: 'center',
            margin: 0,
            lineHeight: 1.4,
            fontWeight: 600,
            width: '100%',
          }}
        >
          {description}
        </p>
      </RoughBox>
    </div>
  );
};

const AwarenessStages: React.FC<AwarenessStagesProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 10,
  titleText = "THE   STAGES OF AWARENESS",
  highlightNumber = "5",
  arrowColor = "#1a5aff",
  headerBackgroundColor = "#0b0c2a",
  bodyBackgroundColor = "#1a5aff",
  textColor = "#ffffff",
  bodyFontSize = 24,
  stages = [
    { title: "Unaware", description: "They aren't aware of their desire or their need to solve the problem—or they won't honestly admit it." },
    { title: "Problem Aware", description: "They know they have a problem to solve, but aren't aware of any specific solutions." },
    { title: "Solution Aware", description: "They know there is a solution to their problem, but they don't know of any specific products to solve it." },
    { title: "Product Aware", description: "They know your product exists, but aren't completely aware of all it does—or aren't convinced of how well it does it." },
    { title: "Most Aware", description: "They know of your product and what it does, but haven't gotten around to purchasing it yet." }
  ]
}) => {
  useFontLoader(["Permanent Marker", "Kalam"]);
  
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Dynamic Sizing Calculations
  const padding = Math.min(width, height) * 0.05;
  const availableWidth = width - (padding * 2);
  const gap = availableWidth * 0.02; // 2% of available width for gaps
  
  // Columns
  const columnCount = stages.length;
  // Subtract total gap space from available width, then divide by columns
  const columnWidth = (availableWidth - (gap * (columnCount - 1))) / columnCount;
  
  // Vertical Proportions
  const titleFontSize = height * 0.07;
  const highlightFontSize = titleFontSize * 1.35;
  const cardHeaderHeight = height * 0.12;
  const cardBodyHeight = height * 0.45;
  
  // Card Text Sizes
  const cardHeaderFontSize = Math.min(columnWidth * 0.13, cardHeaderHeight * 0.35);

  // Arrow Size
  const arrowSize = height * 0.06;

  // Animation Timings
  const titleEntryStart = 0;
  const arrowsEntryStart = 15;
  const cardsEntryStart = 30;

  // Title Animation
  const titleProgress = spring({
    frame: frame - titleEntryStart,
    fps,
    config: { damping: 12 }
  });
  
  const titleScale = interpolate(titleProgress, [0, 1], [0.8, 1]);
  const titleOpacity = interpolate(titleProgress, [0, 1], [0, 1]);

  return (
    <AbsoluteFill style={{ 
      backgroundColor: bgColor, 
      alignItems: 'center', 
      justifyContent: 'center', // Center vertically
      padding: `${padding}px`
    }}>
      
      {/* TITLE SECTION */}
      <div style={{ 
        marginBottom: `${height * 0.03}px`, 
        display: 'flex', 
        flexDirection: 'column', 
        alignItems: 'center',
        opacity: titleOpacity,
        transform: `scale(${titleScale})`,
        width: '100%'
      }}>
        <h1 style={{
          fontFamily: '"Permanent Marker", cursive',
          fontSize: `${titleFontSize}px`,
          color: headerBackgroundColor,
          margin: 0,
          display: 'flex',
          alignItems: 'center',
          gap: `${titleFontSize * 0.3}px`,
          whiteSpace: 'nowrap'
        }}>
          THE <span style={{ color: arrowColor, fontSize: `${highlightFontSize}px`, transform: 'rotate(-5deg)' }}>{highlightNumber}</span> STAGES OF AWARENESS
        </h1>

        {/* ARROWS ROW */}
        <div style={{ 
          display: 'flex', 
          justifyContent: 'center', 
          width: '100%', 
          marginTop: `${height * 0.015}px`,
          gap: `${arrowSize * 0.5}px`,
          height: `${arrowSize}px`
        }}>
          {Array.from({ length: 11 }).map((_, i) => {
            const arrowDelay = arrowsEntryStart + (i * 3);
            const arrowProgress = spring({
              frame: frame - arrowDelay,
              fps,
              config: { stiffness: 100, damping: 20 }
            });

            return (
              <div key={i} style={{ 
                height: arrowSize,
                width: arrowSize,
                transform: `scale(${interpolate(arrowProgress, [0, 1], [0, 1])})`,
                opacity: interpolate(arrowProgress, [0, 0.5], [0, 1])
              }}>
                <MarkerArrow color={arrowColor} progress={interpolate(arrowProgress, [0, 1], [0, 1])} />
              </div>
            );
          })}
        </div>
      </div>

      {/* CARDS CONTAINER */}
      <div style={{ 
        display: 'flex', 
        flexDirection: 'row', 
        justifyContent: 'center',
        width: '100%',
        gap: `${gap}px`,
        alignItems: 'flex-start'
      }}>
        {stages.map((stage, i) => {
          const cardDelay = cardsEntryStart + (i * 5);
          return (
            <StageColumn
              key={i}
              index={i}
              title={stage.title}
              description={stage.description}
              headerColor={headerBackgroundColor}
              bodyColor={bodyBackgroundColor}
              textColor={textColor}
              delay={cardDelay}
              frame={frame}
              fps={fps}
              width={columnWidth}
              headerHeight={cardHeaderHeight}
              bodyHeight={cardBodyHeight}
              headerFontSize={cardHeaderFontSize}
              bodyFontSize={bodyFontSize}
            />
          );
        })}
      </div>

    </AbsoluteFill>
  );
};

export default AwarenessStages;